      .tarjeta.bg-img.bg-img--3.p-4.py-5
        .row.justify-content-center.mb-3
          .col-6
            img.w-85.mb-4(src='@/assets/curso/tema3/12.svg' alt='')
        p.text-center.mb-4 Mantener actitud positiva y demostrar interés genuino.
      .tarjeta.bg-img.bg-img--3.p-4.py-5
